// Modo runOnceForAllItems: recebemos array de items, devolvemos array de items novos
const allInputs = $input.all();
const out = [];

for (const input of allInputs) {
  const raw = input.json.body || input.json;

  const items = (raw.items || []).map(it => {
    let line = `- ${it.quantity}x ${it.name}`;
    if (it.options && it.options.length) {
      const opts = it.options.map(o => o.name).join(", ");
      line += ` (${opts})`;
    }
    if (it.notes) line += `\n   obs: ${it.notes}`;
    line += ` — R$ ${Number(it.line_total).toFixed(2)}`;
    return line;
  }).join("\n");

  const addr = raw.delivery_address && raw.delivery_address.fulfillment === "delivery"
    ? `\n\n📍 Entrega: ${raw.delivery_address.street || ""}, ${raw.delivery_address.number || "s/n"}${raw.delivery_address.complement ? " (" + raw.delivery_address.complement + ")" : ""}\nBairro: ${raw.delivery_address.neighborhood || "—"}${raw.delivery_address.reference ? "\nRef: " + raw.delivery_address.reference : ""}`
    : "\n\n🏪 Retirada no balcão";

  // Bloco de observações
  const geralObs = (raw.notes || "").trim();
  const obsBlock = geralObs ? `\n\n📝 *Observação:* ${geralObs}` : "";

  const payEmoji = { pix: "�� Pix", cash: "💵 Dinheiro", card: "💳 Cartão" }[raw.payment?.method] || "—";
  const payStatus = raw.payment?.status === "confirmed" ? "✅ PAGO" : "⏳ pendente";

  // Cabeçalho conforme fulfillment
  const fulfillment = raw.delivery_address && raw.delivery_address.fulfillment;
  let header;
  let addrBlock;
  if (fulfillment === "mesa") {
    const mesaNum = (raw.delivery_address && raw.delivery_address.mesa) || "?";
    header = `🍽 *NOVO PEDIDO - MESA ${mesaNum}*`;
    addrBlock = `\n\n📍 Atendimento no Salão (Mesa ${mesaNum})`;
  } else {
    const shortId = String(raw.short_id || "—");
    const orderTag = shortId.startsWith("#") ? shortId : ("#" + shortId);
    header = `🍔 *NOVO PEDIDO ${orderTag}*`;
    addrBlock = addr;
  }

  const text = `${header}${addrBlock}\n\n👤 ${raw.customer?.name || "—"}\n📱 ${raw.customer?.phone || "—"}\n\n*Itens:*\n${items || "(sem itens)"}${obsBlock}\n\nSubtotal: R$ ${Number(raw.totals?.subtotal || 0).toFixed(2)}\nEntrega: R$ ${Number(raw.totals?.delivery_fee || 0).toFixed(2)}${Number(raw.totals?.discount || 0) > 0 ? "\nDesconto: -R$ " + Number(raw.totals.discount).toFixed(2) : ""}\n*Total: R$ ${Number(raw.totals?.total || 0).toFixed(2)}*\n\n💰 ${payEmoji} — ${payStatus}`;

  // Telefone do dono para receber a comanda.
  // Prioridade: raw.store_whatsapp (do settings do banco).
  // Fallback seguro se vier vazio ou fake (5511999999999): 5584996327329
  let phone = String(raw.store_whatsapp || "").replace(/\D/g, "");
  if (!phone || phone === "5511999999999" || phone === "11999999999" || phone.length < 10) {
    phone = "5584996327329";
  } else if (!phone.startsWith("55")) {
    phone = "55" + phone;
  }

  const instance = String(raw.evolution_instance_name || raw.tenant_slug || "mendes-teste");

  out.push({
    json: {
      number: phone,
      text: text,
      order_id: raw.order_id,
      short_id: raw.short_id,
      evolution_instance_name: instance,
      _instance: instance
    }
  });
}

return out;

